/* The highlight steps down the rows: each row is lit for 1/n of an n × 3.5s loop, starting
   at its own offset. One keyframes rule per row count (2–8). */
.warp-sdlc-row { background-color: transparent; }
.warp-sdlc-row:first-child { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }

@media (prefers-reduced-motion: no-preference) {
  .warp-sdlc-row,
  .warp-sdlc-row:first-child {
    background-color: transparent;
    animation-duration: calc(var(--warp-sdlc-n) * 3.5s);
    animation-delay: calc((var(--warp-sdlc-i) - var(--warp-sdlc-n)) * 3.5s);
    animation-iteration-count: infinite;
    animation-timing-function: linear;
    animation-fill-mode: both;
  }
}

@keyframes warp-sdlc-lit-2 {
  0%, 49.50% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  50.00%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-3 {
  0%, 32.83% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  33.33%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-4 {
  0%, 24.50% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  25.00%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-5 {
  0%, 19.50% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  20.00%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-6 {
  0%, 16.17% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  16.67%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-7 {
  0%, 13.79% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  14.29%, 100% { background-color: transparent; }
}
@keyframes warp-sdlc-lit-8 {
  0%, 12.00% { background-color: color-mix(in oklab, var(--foreground) 7%, transparent); }
  12.50%, 100% { background-color: transparent; }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import { WarpMedia } from "@foundry/warp-media";
import { WarpSection } from "@foundry/warp-section";
import "./warp-sdlc.css";

export interface WarpSdlcItem {
  title: string;
  text: string;
}

export interface WarpSdlcProps {
  id?: string;
  /** the typed label above the title */
  tag?: string;
  /** shown in brackets after the tag */
  status?: string;
  title: string;
  lead?: string;
  /** the numbered rows (2 to 8 for the stepping highlight) */
  items: WarpSdlcItem[];
  /** the tall product shot at the right (desktop); a placeholder when empty */
  media?: ReactNode;
  /** what the product shot shows, for screen readers */
  mediaLabel?: string;
  className?: string;
}

/** Numbered rows beside a tall product shot; a highlight steps down the rows. */
export function WarpSdlc({ id, tag, status, title, lead, items, media, mediaLabel, className }: WarpSdlcProps) {
  const n = Math.min(Math.max(items.length, 2), 8);
  return (
    <WarpSection id={id} tag={tag} status={status} title={title} lead={lead} className={className}>
      <div className="grid grid-cols-1 border border-border bg-card lg:grid-cols-2">
        <ol className="flex flex-col">
          {items.map((item, i) => (
            <li
              key={item.title}
              className="warp-sdlc-row flex min-h-[7.375rem] gap-4 border-b border-border px-5 pt-6 pb-7 last:border-b-0 lg:min-h-32 lg:gap-3.5 lg:pt-[1.625rem]"
              style={{ "--warp-sdlc-n": n, "--warp-sdlc-i": i, animationName: i < 8 ? `warp-sdlc-lit-${n}` : undefined } as CSSProperties}
            >
              <span className="w-[1.125rem] shrink-0 pt-1 font-mono text-[0.6875rem] text-muted-foreground">{String(i + 1).padStart(2, "0")}</span>
              <div className="min-w-0">
                <h3 className="font-display text-[1.1875rem] leading-[1.5] font-bold tracking-[-0.02em]">{item.title}</h3>
                <p className="mt-1.5 text-[0.8125rem] leading-[1.6] tracking-[calc(0.03em_-_var(--warp-squeeze,0em))] text-muted-foreground">{item.text}</p>
              </div>
            </li>
          ))}
        </ol>
        <WarpMedia label={mediaLabel} className={cn("hidden min-h-full border-l border-border lg:block")}>
          {media}
        </WarpMedia>
      </div>
    </WarpSection>
  );
}
